insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_pfl_v1'
from (values
('113.49.c.1.A',2,'Maya earns $40 a week. Which purchase is a need rather than a want?','["A winter coat when hers no longer fits", "A premium streaming bundle", "A concert ticket", "A third pair of designer sneakers"]'::jsonb,0,'Needs are essentials such as clothing, food and shelter.','original'),
('113.49.c.1.A',2,'A shopper keeps asking, "Do I need this or just want it?" before buying. This habit helps with what?','["Raising credit scores", "Evaluating spending decisions", "Avoiding all taxes", "Increasing interest rates"]'::jsonb,1,'Separating needs from wants prevents overspending.','original'),
('113.49.c.1.B',2,'A person who buys on impulse and rarely checks prices has which money tendency?','["A strong saving propensity", "No money personality", "A strong spending propensity", "A tax strategy"]'::jsonb,2,'Money personality shows habits with spending and saving.','original'),
('113.49.c.1.B',2,'Why is it useful to know your own money personality?','["It guarantees wealth", "It fixes your credit score", "It sets your tax rate", "It helps you spot habits that may hurt or help your finances"]'::jsonb,3,'Self-awareness guides better choices.','original'),
('113.49.c.1.C',2,'Donating to a food bank provides which benefit?','["It helps others in the community and may offer tax benefits", "It guarantees a refund", "It always earns interest", "It raises your credit limit"]'::jsonb,0,'Charitable giving benefits both giver and community.','original'),
('113.49.c.1.D',3,'Which financial goal is SMART (specific, measurable, attainable, relevant, time-bound)?','["Save a lot someday", "Save $1,200 in 12 months by setting aside $100 each month", "Spend less", "Be rich"]'::jsonb,1,'SMART goals have numbers and deadlines.','original'),
('113.49.c.1.D',3,'A goal of paying for college in ten years is an example of which type of goal?','["A tax goal", "An impulse goal", "A long-term goal", "A short-term goal"]'::jsonb,2,'Long-term goals take more than five years.','original'),
('113.49.c.2.A',3,'A reconciliation shows a $25 charge missing from your records. What should you do?','["Ignore it", "Delete the statement", "Close the bank", "Find out what it was and correct your records or dispute it"]'::jsonb,3,'Unexplained charges need follow-up.','original'),
('113.49.c.2.B',3,'An income statement for a month lists what?','["Income received and expenses paid", "Only taxes owed", "Only assets", "Only loans"]'::jsonb,0,'It shows inflows and outflows.','original'),
('113.49.c.2.B',3,'If monthly income is $2,400 and expenses are $2,150, what is the result?','["A surplus of $2,150", "A surplus of $250", "Balanced at zero", "A deficit of $250"]'::jsonb,1,'Income minus expenses equals surplus or deficit.','original'),
('113.49.c.2.C',3,'A budget that includes short-, medium- and long-term goals should do what?','["Wait for a windfall", "Spend all income", "Set aside money for each goal while covering essential expenses", "Ignore goals"]'::jsonb,2,'Budgets turn goals into monthly actions.','original'),
('113.49.c.2.C',3,'Which budget category would an emergency fund contribution belong to?','["Utilities", "Entertainment", "Transportation", "Savings"]'::jsonb,3,'Emergency funds are savings.','original'),
('113.49.c.2.D',3,'Which is an asset?','["A car you own outright", "A past-due bill", "A student loan", "A credit card balance"]'::jsonb,0,'Assets have value; liabilities are what you owe.','original'),
('113.49.c.2.E',3,'A net worth statement is calculated by doing what?','["Adding assets and liabilities", "Subtracting liabilities from assets", "Adding taxes to income", "Subtracting income from expenses"]'::jsonb,1,'Net worth = assets - liabilities.','original'),
('113.49.c.2.E',3,'Assets of $18,000 and liabilities of $7,500 give a net worth of what?','["$25,500", "$18,000", "$10,500", "$7,500"]'::jsonb,2,'18,000 - 7,500 = 10,500.','original'),
('113.49.c.2.F',3,'A $400 car repair that was not budgeted most likely does what?','["Has no effect", "Increases income", "Raises net worth", "Reduces money available for other categories or goals"]'::jsonb,3,'Unplanned spending strains the budget.','original'),
('113.49.c.2.F',3,'Which strategy helps absorb unplanned spending?','["Maintaining an emergency fund", "Paying only minimums", "Skipping a budget", "Spending more"]'::jsonb,0,'An emergency fund cushions surprises.','original'),
('113.49.c.3.A',3,'Which is an employee benefit?','["Interest on a loan", "Employer-paid health insurance contributions", "A parking ticket", "Income tax"]'::jsonb,1,'Benefits add value beyond wages.','original'),
('113.49.c.3.A',3,'A 401(k) employer match is best described as what?','["A tax", "A loan", "Free money added to retirement savings when you contribute", "A fee"]'::jsonb,2,'Matches boost retirement savings.','original'),
('113.49.c.3.B',3,'Which payroll tax funds Social Security and Medicare?','["Sales tax", "Property tax", "Excise tax", "FICA"]'::jsonb,3,'The Federal Insurance Contributions Act tax is deducted from paychecks.','original'),
('113.49.c.3.B',3,'Which is usually deducted from a paycheck?','["Federal income tax", "Property tax", "Sales tax", "Tuition"]'::jsonb,0,'Employers withhold income tax.','original'),
('113.49.c.3.C',3,'Gross pay is what?','["Only overtime", "Total earnings before deductions", "Only bonuses", "Pay after taxes"]'::jsonb,1,'Net pay is gross minus deductions.','original'),
('113.49.c.3.C',3,'Gross pay is $1,000 and deductions are $230. Net pay is what?','["$700", "$1,230", "$770", "$230"]'::jsonb,2,'1,000 - 230 = 770.','original'),
('113.49.c.4.A',3,'Which is a cost of owning a home that renters usually avoid?','["Security deposit", "Lease fee", "Monthly rent", "Property taxes and maintenance"]'::jsonb,3,'Owners pay taxes, upkeep and repairs.','original'),
('113.49.c.4.A',3,'A benefit of owning a home compared with renting is what?','["Building equity as the loan is paid down", "No monthly payment", "No repairs", "No taxes"]'::jsonb,0,'Equity is ownership value.','original'),
('113.49.c.4.B',3,'A benefit of leasing a vehicle rather than buying is what?','["Ownership after the term", "Lower monthly payments, but no ownership at the end", "No fees", "Unlimited mileage"]'::jsonb,1,'Leases often have mileage limits and no equity.','original'),
('113.49.c.4.B',3,'Buying a car and keeping it for years is often cheaper in the long run because what?','["Repairs never occur", "Gas is free", "Payments end and you keep the vehicle", "Insurance is free"]'::jsonb,2,'Ownership avoids repeated lease payments.','original'),
('113.49.c.4.C',3,'Rent-to-own arrangements usually cost more than paying cash because what?','["Interest is zero", "There are no payments", "The item is free", "Total payments include high fees and markups"]'::jsonb,3,'Compare total cost, not just weekly payments.','original'),
('113.49.c.4.C',3,'Which payment method usually has the highest total cost for the same item?','["Store credit with a high interest rate carried for months", "Paying cash", "Using a debit card", "Saving first"]'::jsonb,0,'Interest increases total cost.','original'),
('113.49.c.4.D',3,'Which strategy helps a consumer make a smart purchase?','["Skipping research", "Comparing unit prices and reading reviews", "Buying the first option", "Following a slogan"]'::jsonb,1,'Informed buying saves money.','original'),
('113.49.c.4.D',3,'A 12-ounce box costs $3.00 and a 20-ounce box costs $4.60. Which is the better unit price?','["The 12-ounce box at $0.20 per ounce", "The 12-ounce box at $0.25 per ounce", "The 20-ounce box at $0.23 per ounce", "They are equal"]'::jsonb,2,'4.60 / 20 = 0.23; 3.00 / 12 = 0.25.','original'),
('113.49.c.5.A',3,'A good short-term saving goal is to do what?','["Buy a house now", "Spend savings on wants", "Invest everything in one stock", "Build an emergency fund covering several months of expenses"]'::jsonb,3,'Emergency funds protect against surprises.','original'),
('113.49.c.5.A',3,'Where is an emergency fund best kept?','["In an easily accessible savings account", "Locked in a long-term fund", "In a risky stock", "Under a mattress only"]'::jsonb,0,'Liquidity matters for emergencies.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
