       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_pfl_v1'
from (values
('113.49.c.5.B',3,'Saving for a house down payment in five years is an example of what?','["Short-term saving", "Intermediate-term saving and investing", "Spending", "Retirement saving only"]'::jsonb,1,'Goals of several years are intermediate-term.','original'),
('113.49.c.5.B',3,'For a goal five years away, a moderate mix of savings and lower-risk investments is common because what?','["Risk is irrelevant", "Taxes are zero", "There is time to earn returns but limited time to recover from losses", "Money cannot grow"]'::jsonb,2,'Time horizon affects risk.','original'),
('113.49.c.5.C',3,'A charitable contribution to a qualified nonprofit may do what on a tax return?','["Increase the tax owed", "Raise income", "Cancel all taxes", "Reduce taxable income if deductions are itemized"]'::jsonb,3,'Charitable deductions can lower tax.','original'),
('113.49.c.5.C',3,'To claim a charitable deduction, a donor should keep what?','["Receipts or acknowledgment letters", "Nothing", "Social media posts", "Only a verbal note"]'::jsonb,0,'Records support deductions.','original'),
('113.49.c.5.D',3,'A long-term investing strategy for retirement should emphasize what?','["Waiting until age 60", "Consistent contributions over many years", "Spending savings", "Avoiding investing"]'::jsonb,1,'Time and consistency build wealth.','original'),
('113.49.c.5.D',3,'Which account type offers tax advantages for retirement saving?','["Checking account", "Payday loan", "401(k) or IRA", "Credit card"]'::jsonb,2,'Retirement accounts provide tax benefits.','original'),
('113.49.c.6.A',3,'Banks and credit unions help savers by doing what?','["Taking money without return", "Selling insurance only", "Setting taxes", "Holding deposits safely and paying interest"]'::jsonb,3,'Financial institutions channel savings to borrowers.','original'),
('113.49.c.6.A',3,'The stock market allows investors to do what?','["Buy and sell ownership shares in companies", "Set interest rates", "Collect taxes", "Print money"]'::jsonb,0,'Markets connect investors and companies.','original'),
('113.49.c.6.B',3,'Compound growth means that interest is earned on what?','["Neither", "Both the original deposit and previously earned interest", "Only the interest", "Only the original deposit"]'::jsonb,1,'Growth accelerates over time.','original'),
('113.49.c.6.B',3,'$1,000 grows at 5 percent compounded annually. After one year the balance is $1,050. After the second year it is closest to what?','["$1,050.00", "$1,200.00", "$1,102.50", "$1,100.00"]'::jsonb,2,'1,050 x 1.05 = 1,102.50.','original'),
('113.49.c.6.C',3,'Compared with a checking account, a savings account usually offers what?','["Unlimited checks", "Higher fees", "No interest", "Higher interest but limits on withdrawals"]'::jsonb,3,'Savings are for accumulating money.','original'),
('113.49.c.6.D',3,'Stocks generally offer which risk-return trade-off compared with bonds?','["Higher potential return with greater risk", "Lower return with greater risk", "No risk", "Guaranteed return"]'::jsonb,0,'Risk and return are related.','original'),
('113.49.c.6.D',3,'A mutual fund helps investors by doing what?','["Eliminating all risk", "Pooling money to buy a diversified mix of investments", "Guaranteeing profit", "Setting taxes"]'::jsonb,1,'Diversification spreads risk.','original'),
('113.49.c.7.A',3,'Which is a cost people face in retirement?','["Child care for toddlers", "Payroll tax on wages", "Health care and possible long-term care", "School tuition only"]'::jsonb,2,'Medical costs rise with age.','original'),
('113.49.c.7.A',3,'Many retirees need money for which basic expense?','["No expenses", "Only taxes", "Only entertainment", "Housing and daily living costs"]'::jsonb,3,'Living costs continue in retirement.','original'),
('113.49.c.7.B',3,'Which is a common source of retirement income?','["Social Security benefits", "A student loan", "A payday loan", "A credit card"]'::jsonb,0,'Social Security replaces part of earnings.','original'),
('113.49.c.7.B',3,'A pension is best described as what?','["A student grant", "A regular payment from an employer plan after retirement", "A credit line", "A tax refund"]'::jsonb,1,'Pensions pay retirees.','original'),
('113.49.c.7.C',3,'Starting to save for retirement at 25 instead of 45 helps because of what?','["Interest is fixed", "Taxes are lower", "Compound growth has more years to work", "Prices are lower"]'::jsonb,2,'Time magnifies growth.','original'),
('113.49.c.7.C',3,'Saving a sufficient percentage of income each year matters because what?','["Retirement is short", "Social Security covers everything", "Savings are taxed away", "Small amounts may not fund retirement needs"]'::jsonb,3,'Adequate savings are required.','original'),
('113.49.c.8.A',3,'Which source of credit is generally the most expensive?','["A payday loan", "A bank loan", "A credit union loan", "A student loan"]'::jsonb,0,'Payday loans have very high APRs.','original'),
('113.49.c.8.A',3,'A title loan requires a borrower to do what?','["Pay no interest", "Use a vehicle title as collateral", "Skip repayment", "Provide no security"]'::jsonb,1,'Failure to repay can mean losing the vehicle.','original'),
('113.49.c.8.B',3,'Revolving credit, such as a credit card, allows a borrower to do what?','["Borrow once only", "Skip interest", "Borrow repeatedly up to a limit", "Avoid payments"]'::jsonb,2,'Balances can be reused.','original'),
('113.49.c.8.B',3,'An auto loan with equal monthly payments for 60 months is what type of credit?','["Charge card", "Revolving credit", "Unsecured credit", "Installment credit"]'::jsonb,3,'Installment loans have fixed payments.','original'),
('113.49.c.8.C',3,'Taking on a $350 monthly loan payment affects a budget by doing what?','["Reducing the money available for other expenses and goals", "Having no effect", "Raising net worth immediately", "Increasing income"]'::jsonb,0,'Debt payments are a fixed expense.','original'),
('113.49.c.8.C',3,'Borrowing to buy a depreciating item can do what to net worth?','["Raise it", "Lower it, because liabilities may exceed asset value", "Have no effect", "Double it"]'::jsonb,1,'Debt rises while value falls.','original'),
('113.49.c.9.A',3,'Which of the three Cs of credit refers to a borrower''s reliability and history of repaying?','["Capacity", "Collateral", "Character", "Capital"]'::jsonb,2,'Lenders consider character, capacity and collateral.','original'),
('113.49.c.9.A',3,'Capacity in credit evaluation means what?','["The interest rate", "The loan term", "The size of the bank", "The borrower''s ability to repay from income"]'::jsonb,3,'Income relative to debts matters.','original'),
('113.49.c.9.B',3,'Consumers can get a free credit report from the three major credit bureaus at what site?','["AnnualCreditReport.com", "A social media app", "Any shopping website", "A ticket seller"]'::jsonb,0,'The official site is annualcreditreport.com.','original'),
('113.49.c.9.B',3,'A credit score is best described as what?','["A tax rate", "A number summarizing how risky a borrower appears", "A bank balance", "A salary"]'::jsonb,1,'Higher scores mean lower risk.','original'),
('113.49.c.9.C',3,'Why check credit reports regularly?','["To avoid taxes", "To close accounts", "To catch errors and signs of identity theft", "To raise interest rates"]'::jsonb,2,'Mistakes can lower scores.','original'),
('113.49.c.9.C',3,'If you find an error on a credit report, you should do what?','["Pay a stranger", "Close all accounts", "Ignore it", "Dispute it with the credit bureau in writing"]'::jsonb,3,'Disputes can correct errors.','original'),
('113.49.c.9.D',3,'Which event could lead to bankruptcy?','["Large unpaid medical bills after job loss", "A savings deposit", "A raise", "A tax refund"]'::jsonb,0,'Unexpected hardship plus debt can overwhelm a household.','original'),
('113.49.c.9.D',3,'Bankruptcy is a legal process in which what happens?','["A person pays no taxes", "A person seeks relief from debts they cannot repay", "Credit is improved", "A bank closes"]'::jsonb,1,'It has long-term credit consequences.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
